// DocRecord describes a record.
type DocRecord struct {
 // DocField belongs to the field.
 DocField int
 DocTrailing string `json:"x"` // DocTrailing is trailing.
 // Shared field documentation.
 DocLeft, DocRight bool
 DocMulti string /*First sentence.*/ /*Second sentence.*/
 DocBlank int

 // Detached comment.

 DocDetached int
}
// Group documentation.
var (
 DocGroup int
 // Own documentation.
 DocOwn int
 DocNested int = func() int {
 // Nested group.
 var (local int)
 return local
 }()
 DocAfter int
 DocFallback int // Trailing loses to the group.
)
var DocTail int // DocTail has a trailing comment.
